# Lesson 14 of MKTG90037: measuring value to the firm (Week 9, first part): EVA and the Balanced Scorecard. Brand: Coles (FY26
# results; its capital employed is not in the notes, so EVA is discussed, not computed). The NOPAT figures are the lecture's own
# illustration; the Domino's and Pizza Hut price war is the lecture's case. Instruments: profit or value? (Dial), scorecard (Place).
from mk import *  # noqa: F403


def L14(CID):
    SK = 'mk.firm-value'
    zones = [dict(id='fin', label=T('Financial: how do we look to shareholders?', '财务：股东怎么看我们？')), dict(id='cus', label=T('Customer: how do customers see us?', '顾客：顾客怎么看我们？')),
             dict(id='int', label=T('Internal processes: what must we excel at?', '内部流程：我们必须擅长什么？')), dict(id='lrn', label=T('Innovation and learning: can we keep improving?', '创新与学习：我们能持续改进吗？'))]
    chips = [
        dict(id='f1', label=T('Group EBIT excluding significant items: AUD 2,322 million (Coles FY26)', '剔除重大项目后的集团 EBIT：23.22 亿澳元（Coles 2026 财年）'), zone='fin', why=T('A profit measure: the financial perspective.', '利润指标：财务视角。')),
        dict(id='f2', label=T('Sales revenue growth and return on investment', '销售收入增长与投资回报率'), zone='fin', why=T('Sample financial measures.', '财务视角的示例指标。')),
        dict(id='c1', label=T('About 10.3 million active Flybuys members', '约 1,030 万活跃 Flybuys 会员'), zone='cus', why=T('The number and loyalty of customers.', '顾客的数量与忠诚度。')),
        dict(id='c2', label=T('Customer satisfaction and repeat customers', '顾客满意度与回头客'), zone='cus', why=T('Sample customer measures.', '顾客视角的示例指标。')),
        dict(id='i1', label=T('Customer fulfilment centres are EBITDA-positive', '客户履约中心 EBITDA 为正'), zone='int', why=T('Whether a key process works economically.', '一项关键流程在经济上是否行得通。')),
        dict(id='i2', label=T('Order processing time and defect rate', '订单处理时间与缺陷率'), zone='int', why=T('Sample process measures.', '流程视角的示例指标。')),
        dict(id='l1', label=T('Highest ever team engagement score in the mysay survey (May 2026)', 'mysay 调查中历史最高的团队敬业度得分（2026 年 5 月）'), zone='lrn', why=T('The people’s ability to learn and improve.', '人的学习与改进能力。')),
        dict(id='l2', label=T('New product introduction rate and hours of training', '新产品推出速度与培训小时数'), zone='lrn', why=T('Sample innovation and learning measures.', '创新与学习视角的示例指标。')),
    ]
    return dict(
        id=f'{CID}-firm-value',
        title=T('How do I know the value was created?', '怎么知道价值真的创造出来了？'),
        description=T('Why a profitable firm can still destroy value (EVA), why one number is not enough (Balanced Scorecard), and what a price war shows, with Coles.', '为什么盈利的企业仍可能毁灭价值（EVA）、为什么一个数字不够（平衡计分卡）、价格战说明什么，案例是 Coles。'),
        minutes=40,
        skills=[{'id': SK, 'name': T('Explaining and applying EVA and the Balanced Scorecard', '解释并应用 EVA 和平衡计分卡')}],
        misconceptions=[
            {'id': 'eva-is-profit', 'description': T('economic value added is the same as accounting profit', 'EVA 和会计利润是一回事')},
            {'id': 'price-cut-wins', 'description': T('a price cut that raises sales always raises value for the firm', '一次带来销量增长的降价总能提高企业价值')},
        ],
        steps=[
            read('puzzle', T('A pizza that costs more to make than it sells for', '成本比售价还高的披萨'),
                 p(T("In 2014 the head office of a pizza chain in Australia forced its franchisees to cut prices, to a range from 4.95 to 8.95 dollars. The estimated cost to produce a 4.95 dollar pizza was about 5.50. Eighty franchisees took a class action, which grew to 280, and a court blocked the directive. In 2016 new owners acquired the master franchise licence.",
                     "2014 年，澳大利亚一家披萨连锁的总部强令加盟商降价，价格区间为 4.95 至 8.95 澳元。一个 4.95 澳元披萨的估计生产成本约 5.50 澳元。80 家加盟商提起集体诉讼，后来增加到 280 家，法院阻止了这一指令。2016 年新的所有者收购了总特许经营权。")),
                 p(T("Sales go up in a price war. Does value? To answer you need a measure of value to the **firm**, as lesson 1 gave you one for the customer.", "价格战中销量会上升。价值会吗？要回答，你需要一个衡量**企业**价值的指标，就像第 1 课给了你衡量顾客价值的方法。")), chapter=CH['puzzle']),
            predict('guess', SK, T("A firm reports a profit. Can it still be destroying value?", "一家企业报告了利润。它还可能在毁灭价值吗？"),
                    [(T("Yes: if the profit is smaller than the cost of the capital tied up to earn it", "可能：如果利润小于为赚取它而占用资本的成本"), True),
                     (T("No: profit means value was created", "不可能：有利润就说明创造了价值"), T("Accounting profit ignores the cost of the money invested. Airlines can show a profit and a negative EVA.", "会计利润忽略了所投入资金的成本。航空公司可以有利润，却 EVA 为负。")),
                     (T("Only if sales are falling", "只有在销量下降时"), T("Sales are not part of the test.", "销量不在这个检验里。")),
                     (T("Only if the firm pays no tax", "只有在企业不交税时"), T("Tax is already taken off in the measure.", "这个指标里已经扣除了税。"))],
                    T("That is what **economic value added (EVA)** shows: profit after tax **minus a charge for the capital used**. Try it.", "这正是**经济增加值（EVA）**要说明的：税后利润**减去所用资本的成本**。试一试。")),
            read('touch', T('Profit, or value?', '利润，还是价值？'),
                 p(T("The first four rows are the lecture’s illustration of a firm’s operating result (a unit of money is not stated); capital employed and the cost of capital are set by you. All figures are illustrative.", "前四项是课程里一家企业经营结果的示例（未注明货币单位）；占用资本和资本成本由你设定。所有数字都是示意。")),
                 dial(T('Sliders for sales, costs, tax, capital employed and cost of capital; outputs show operating profit, profit after tax, the capital charge, and EVA.', '销售、成本、税率、占用资本和资本成本的滑块；输出为营业利润、税后利润、资本成本，以及 EVA。'),
                      sliders=[dict(id='sales', label=T('Net sales', '净销售额'), min=100000, max=200000, step=1000, value=150000), dict(id='cogs', label=T('Cost of sales', '销货成本'), min=100000, max=190000, step=1000, value=135000),
                               dict(id='dep', label=T('Depreciation, selling and admin expenses', '折旧与销售管理费用'), min=0, max=30000, step=500, value=9000), dict(id='tax', label=T('Tax rate', '税率'), min=0, max=50, step=1, value=40, unit='%'),
                               dict(id='cap', label=T('Capital employed', '占用资本'), min=10000, max=120000, step=1000, value=30000), dict(id='wacc', label=T('Cost of capital (WACC)', '资本成本（WACC）'), min=2, max=20, step=0.5, value=10, unit='%', dec=1)],
                      outs=[dict(id='op', label=T('Operating profit', '营业利润'), expr='sales-cogs-dep', dec=0), dict(id='nopat', label=T('Profit after tax (NOPAT)', '税后营业利润（NOPAT）'), expr='op*(1-tax/100)', dec=0),
                            dict(id='charge', label=T('Capital charge', '资本成本额'), expr='cap*wacc/100', dec=0), dict(id='eva', label=T('Economic value added', '经济增加值（EVA）'), expr='nopat-charge', dec=0)],
                      plot=dict(x='cap', ys=[dict(out='nopat', label=T('profit after tax', '税后利润'), color='#1F8A5B'), dict(out='charge', label=T('capital charge', '资本成本额'), color='#E4572E')], ymin=0, ylabel=T('money', '金额'), xlabel=T('capital employed', '占用资本')),
                      presets=[dict(label=T('The lecture’s figures', '课程里的数字'), set=dict(sales=150000, cogs=135000, dep=9000, tax=40, cap=30000, wacc=10)), dict(label=T('Capital-hungry, like an airline', '资本密集，像航空公司'), set=dict(sales=150000, cogs=135000, dep=9000, tax=40, cap=80000, wacc=10))],
                      notes=[dict(when='nopat>0&&eva<0', text=T('**A profit, but negative EVA**: the firm did not earn its cost of capital, so it destroyed value.', '**有利润，但 EVA 为负**：企业没有赚到资本成本，所以毁灭了价值。')),
                             dict(when='eva>=0&&nopat>0', text=T('**EVA is positive**: the return on capital exceeds its cost.', '**EVA 为正**：资本回报超过了资本成本。')), dict(when='nopat<=0', text=T('A loss: EVA is negative before the capital charge is even counted.', '亏损：还没算资本成本，EVA 就已经是负的。'))],
                      caption=T("The operating figures follow the lecture’s illustration (150,000 sales, 135,000 cost of sales, 9,000 other costs, 40% tax); capital and cost of capital are set here only to show the mechanism.", "经营数字沿用课程里的示例（销售 150,000、销货成本 135,000、其他费用 9,000、税率 40%）；资本和资本成本只是为演示机制而设。"), height=900),
                 chapter=CH['touch']),
            read('touch2', T('One number is never enough', '一个数字永远不够'),
                 p(T("EVA looks backward at results. The **Balanced Scorecard** adds three forward-looking views. Place eight measures, four of them from Coles’ FY26 results and pages.", "EVA 回头看结果。**平衡计分卡**增加了三个面向未来的视角。把八个指标放进去，其中四个来自 Coles 2026 财年的业绩和页面。")),
                 place(T('Eight measures to place on the four perspectives of the Balanced Scorecard.', '八个指标，放到平衡计分卡的四个视角上。'), zones, chips, cols=2,
                       done=T("Four perspectives (Kaplan and Norton): **financial** (how do we appear to shareholders?), **customer** (to our customers?), **internal business process** (what must we excel at?), **innovation and learning** (can we change and improve?). It complements EVA: EVA reports **outcomes**, the scorecard shows **how value is created**.", "四个视角（Kaplan 和 Norton）：**财务**（股东怎么看我们？）、**顾客**（顾客怎么看我们？）、**内部业务流程**（我们必须擅长什么？）、**创新与学习**（我们能改变和改进吗？）。它是对 EVA 的补充：EVA 报告**结果**，计分卡显示**价值怎样创造出来**。"), height=1000)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("There are two sides to value: **value to the customer** (what the customer prefers and evaluates about attributes, performance and consequences that help them reach their goals, Woodruff) and **value to the firm** (sales, profitability, market share). Marketing is the process of engaging customers and creating value **in order to capture value in return** (Kotler and Armstrong). A firm should earn a return on capital; if the long-run return is not satisfactory it should be corrected or the activity abandoned (Sloan).", "价值有两面：**对顾客的价值**（顾客对有助于实现其目标的属性、表现和使用结果的偏好与评价，Woodruff）和**对企业的价值**（销售、盈利、市场份额）。营销是吸引顾客并创造价值、**以便换回价值**的过程（Kotler 和 Armstrong）。企业应当赚取资本回报；如果长期回报不满意，就应纠正或放弃这项活动（Sloan）。")),
                 h(T('Economic value added', '经济增加值（EVA）')),
                 ul(T("**EVA = economic profit** = NOPAT − capital charge; developed by Stern Stewart in the late 1980s. It is **not accounting profit**: its costs include expenses **and the cost of capital**, the minimum acceptable return.", "**EVA = 经济利润** = NOPAT − 资本成本额；由 Stern Stewart 在 1980 年代末提出。它**不是会计利润**：成本既包括费用，也包括**资本成本**，即最低可接受的回报。"),
                    T("**NOPAT**: net operating profit after tax (sales − cost of sales − depreciation − selling and admin = operating profit; less tax). **Capital employed**: net operating working capital, net property and equipment, goodwill and other operating assets (exclude non-operating assets). **Cost of capital**: the weighted average cost of capital, a percentage.", "**NOPAT**：税后净营业利润（销售 − 销货成本 − 折旧 − 销售管理费用 = 营业利润；再减税）。**占用资本**：净营运资本、净固定资产、商誉和其他经营性资产（不含非经营性资产）。**资本成本**：加权平均资本成本，一个百分比。"),
                    T("In **capital-intensive** industries such as airlines, accounting profit can be positive and EVA negative; falling costs can turn it positive.", "在航空这类**资本密集**行业，会计利润可能为正而 EVA 为负；成本持续下降可以使它转正。"),
                    T("**Drivers**: sales growth without extra investment; higher prices (stronger brands, price sensitivity by segment, communicating value, innovation); lower costs (more effective marketing spend, fixed-variable balance, scale and learning, outsourcing); and the capital charge (acquisitions, working capital).", "**驱动因素**：不增加投资的销售增长；更高的价格（更强的品牌、按细分的价格敏感度、传达价值、创新）；更低的成本（营销支出更有效、固定与可变成本平衡、规模与学习、外包）；以及资本成本额（并购、营运资本）。"),
                    T("**Limits**: short-term focus; reports results without offering solutions; does not show the causal link between marketing decisions and firm value; uses no micro data.", "**局限**：短期导向；只报告结果，不提供办法；不显示营销决策与企业价值之间的因果；不使用微观数据。")),
                 h(T('Balanced Scorecard', '平衡计分卡')),
                 p(T("The **Balanced Scorecard** (Kaplan and Norton) turns vision and strategy into objectives, measures, targets and initiatives on four perspectives, and tracks how a strategy is implemented. Sample measures: **customer** (market share and change in customers, satisfaction, repeat customers, on-time delivery); **internal** (order time, units per hour and defect rate, warranty claims, repair time); **innovation and learning** (new product rate, training hours, suggestions implemented, employees with access to customer data); **financial** (revenue growth, gross margin growth, ROI). Because EVA is backward-looking, the scorecard supplies the forward-looking view.", "**平衡计分卡**（Kaplan 和 Norton）把愿景和战略转化为四个视角上的目标、指标、目标值和行动，并追踪战略如何落地。示例指标：**顾客**（市场份额与顾客数变化、满意度、回头客、准时交付）；**内部**（订单时间、每小时产量与缺陷率、保修索赔、维修时间）；**创新与学习**（新产品推出速度、培训小时、被采纳的建议、能接触顾客数据的员工）；**财务**（收入增长、毛利增长、ROI）。因为 EVA 回头看，计分卡补上了面向未来的视角。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Use Coles’ FY26 results: Group EBIT excluding significant items AUD 2,322 million; Supermarkets EBIT 2,365; Liquor EBIT 59, down 47.8%. Capital employed is not given, so you cannot compute EVA. Write four sentences: what these numbers show, **why they are not EVA**, and which scorecard perspective would show whether Liquor’s fall will last.", "用 Coles 2026 财年的业绩：剔除重大项目后集团 EBIT 23.22 亿澳元；超市 EBIT 23.65 亿；酒类 EBIT 5,900 万，下降 47.8%。没有给出占用资本，所以算不了 EVA。写四句话：这些数字说明什么、**为什么它们不是 EVA**，以及哪个计分卡视角能显示酒类的下滑会不会持续。"),
                    [T("Uses true figures: EBIT 2,322; Supermarkets 2,365; Liquor 59, down 47.8%", "用真实数字：EBIT 2,322；超市 2,365；酒类 59，下降 47.8%"), T("Says EBIT is a profit before the charge for capital, so EVA needs capital employed and the cost of capital", "说明 EBIT 是扣除资本成本额之前的利润，所以 EVA 需要占用资本和资本成本"),
                     T("Names the customer or internal perspective, or innovation and learning, as showing the causes, with a reason", "点出顾客或内部流程，或创新与学习视角能显示原因，并给理由"), T("Does not invent a capital figure", "不编造资本数字")],
                    T("Coles’ Group EBIT excluding significant items was 2,322 million dollars in FY26, with Supermarkets at 2,365 and Liquor at 59, down 47.8%, so supermarkets carry the group and liquor is weak. EBIT is not EVA: it is profit before tax and before any charge for the capital used, and the results give no capital employed, so I cannot say whether the group earns its cost of capital. To see whether Liquor’s fall will last I would look at the customer perspective, such as Liquor’s repeat customers and share, because the financial figure only reports the outcome, not why shoppers are leaving.",
                      "Coles 2026 财年剔除重大项目后的集团 EBIT 为 23.22 亿澳元，其中超市 23.65 亿、酒类 5,900 万，下降 47.8%，所以集团靠超市支撑，酒类疲软。EBIT 不是 EVA：它是扣税前、也未扣所用资本成本的利润，而业绩里没有给出占用资本，所以我无法说集团是否赚到了资本成本。要看酒类的下滑会不会持续，我会看顾客视角，如酒类的回头客和份额，因为财务数字只报告结果，不说明购物者为何流失。"),
                    T("Use the numbers, say what they cannot show, name the perspective that can.", "用数字，说明它们不能说明什么，指出哪个视角能说明。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("After a price cut sales rise 30% and the head office declares it a success. What is the problem with that conclusion?", "降价后销量增长 30%，总部宣布成功。这个结论的问题在哪？"),
                   [(T("Sales growth is not value to the firm: if margin per unit falls below cost, profit and EVA can fall", "销量增长不等于企业价值：如果单位毛利跌到成本以下，利润和 EVA 可能下降"), True), (T("None: more sales always means more value", "没问题：销量越多价值越大"), T("The pizza case shows a price below cost loses money on every sale.", "披萨案例说明价格低于成本，每卖一个都亏钱。")),
                    (T("It should use the customer’s perspective only", "只该用顾客视角"), T("Customer value matters, but the question here is value to the firm.", "顾客价值也重要，但这里问的是企业价值。"))],
                   T("Value to the firm needs profit and the cost of capital, not just sales.", "企业价值需要利润和资本成本，不只是销量。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 13: when buying costs more once transaction costs are added, the firm should…", "来自第 13 课：加上交易成本后外购反而更贵时，企业应该……"),
                   [(T("make it in-house", "自己做"), True), (T("always still buy", "仍然外购"), T("Total cost decides.", "由总成本决定。"))], T("Total cost logic.", "总成本逻辑。"), first=True),
            recall('r2', SK, T("From lesson 11: shared value is measured as…", "来自第 11 课：共享价值怎样衡量……"),
                   [(T("the sum of financial value and societal value", "财务价值与社会价值之和"), True), (T("profit alone", "仅利润"), T("That would ignore the societal side.", "那会忽略社会一侧。"))], T("Two kinds of value added together.", "两类价值相加。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain economic value added and the Balanced Scorecard as measures of firm value. (b) Apply them to Coles in Australia. (c) Make two recommendations.", "题目。(a) 解释经济增加值和平衡计分卡这两种企业价值的衡量方法。(b) 把它们应用到澳大利亚的 Coles。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("EVA = NOPAT less the capital charge; it is not accounting profit", "EVA = NOPAT 减资本成本额；不是会计利润"), T("Components: NOPAT, capital employed, cost of capital", "构成：NOPAT、占用资本、资本成本"),
                         T("Balanced Scorecard: four perspectives, objectives, measures, targets and initiatives", "平衡计分卡：四个视角，目标、指标、目标值和行动"), T("Complementary: EVA backward-looking outcome, scorecard forward-looking drivers; EVA limits", "互补：EVA 回头看结果，计分卡面向未来看驱动；EVA 的局限")],
                        T("Economic value added is the profit left after tax once a charge for the capital employed is deducted, so it shows whether a firm earns more than its cost of capital; it is not accounting profit. Its parts are net operating profit after tax, capital employed and the weighted cost of capital. EVA looks backward and does not show causes. The Balanced Scorecard complements it with four perspectives, financial, customer, internal process, and innovation and learning, each with objectives, measures, targets and initiatives, so managers can see how value is created and track strategy.",
                          "经济增加值是税后利润扣除占用资本的成本之后剩下的部分，所以它显示企业是否赚得比资本成本更多；它不是会计利润。它的组成是税后净营业利润、占用资本和加权资本成本。EVA 回头看，不显示原因。平衡计分卡用四个视角（财务、顾客、内部流程、创新与学习）补充它，每个视角有目标、指标、目标值和行动，使管理者能看到价值怎样创造并追踪战略。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Uses true Coles figures (sales 45,580 million, EBIT excluding significant items 2,322 million, Liquor EBIT down 47.8%, 311 million of cost savings)", "用真实的 Coles 数字（销售 455.80 亿、剔除重大项目后 EBIT 23.22 亿、酒类 EBIT 下降 47.8%、3.11 亿成本节省）"), T("Explains why EBIT is not EVA and what information is missing", "解释为什么 EBIT 不是 EVA 以及缺什么信息"),
                         T("Puts Coles facts on at least three perspectives with cause and effect", "把 Coles 的事实放到至少三个视角上并说明因果"), T("Notes a limit of the measures", "指出这些指标的局限")],
                        T("Coles’ FY26 revenue was 45,580 million dollars and EBIT excluding significant items 2,322 million, but EBIT is before the charge for capital, so EVA needs capital employed, which the results do not give, and a retailer with many stores and distribution centres is capital-intensive. On the scorecard: financially, supermarkets earned 2,365 million while Liquor’s EBIT fell 47.8%; for customers, about 10.3 million active Flybuys members and online sales up 26.4% show a growing relationship; internally, fulfilment centres were EBITDA-positive and cost savings of 311 million dollars were reinvested in value, which links process to price; for learning, the engagement score reached its highest ever. The limit is that these show state, not cause: for example, Liquor’s fall needs customer data to explain.",
                          "Coles 2026 财年收入为 455.80 亿澳元，剔除重大项目后 EBIT 为 23.22 亿，但 EBIT 在扣资本成本之前，所以 EVA 需要占用资本，业绩里没有，而拥有大量门店和配送中心的零售商是资本密集型的。在计分卡上：财务上，超市赚了 23.65 亿，酒类 EBIT 下降 47.8%；顾客方面，约 1,030 万活跃 Flybuys 会员和线上销售增长 26.4% 显示关系在增强；内部流程方面，履约中心 EBITDA 为正，3.11 亿澳元成本节省再投入价格，把流程和价格联系起来；学习方面，敬业度得分达到历史最高。局限是这些显示的是状态而非原因：例如酒类的下滑需要顾客数据来解释。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two from the analysis (compute and report returns on capital by segment; add customer measures to explain Liquor)", "恰好两条，从分析里推出（按分部计算并报告资本回报；加入顾客指标来解释酒类）"), T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, report return on capital by segment, including a charge for capital, so managers see whether Liquor and the online business earn more than they cost, because EBIT hides capital use. The risk is allocation disputes, so fix the rules once a year. Second, add customer measures for Liquor, such as repeat rate and share by store type, to find out why profit fell 47.8%, because the scorecard’s customer view explains what the financial view cannot. The risk is slow data, so start with Flybuys data that already exists.",
                          "第一，按分部报告资本回报，包含资本成本，让管理者看到酒类和线上业务是否赚得比成本多，因为 EBIT 掩盖了资本使用。风险是分摊上的争议，所以每年固定一次规则。第二，为酒类增加顾客指标，如按门店类型的回头率和份额，找出利润为何下降 47.8%，因为计分卡的顾客视角能解释财务视角解释不了的东西。风险是数据太慢，所以先用已有的 Flybuys 数据。")),
                       ),
    )
